@using sv_d4cc016799464cf8937cdbb1f58ebe1c.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
    </div>
}

<div class="catalog-container">
    <!-- Left Sidebar -->
    <aside class="catalog-sidebar">
        <h4>Filters</h4>

        <div class="filter-section">
            <h5>Categories</h5>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="(e) => ToggleCategory(category, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                    </div>
                }
            }
            else
            {
                <p><em>Loading categories...</em></p>
            }
        </div>

        <div class="filter-section">
            <h5>Price Range</h5>
            <div class="mb-2">
                <label for="minPrice">Min Price</label>
                <input type="number" id="minPrice" class="form-control" placeholder="Min"
                       @bind="minPrice" step="0.01" min="0" />
            </div>
            <div class="mb-2">
                <label for="maxPrice">Max Price</label>
                <input type="number" id="maxPrice" class="form-control" placeholder="Max"
                       @bind="maxPrice" step="0.01" min="0" />
            </div>
        </div>

        <div class="filter-section">
            <div class="form-check">
                <input class="form-check-input" type="checkbox" id="inStockOnly"
                       @bind="inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary w-100 mb-2" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <!-- Main Content -->
    <main class="catalog-main">
        <!-- Toolbar -->
        <div class="catalog-toolbar">
            <div class="sort-control">
                <label for="sortBy">Sort by:</label>
                <select id="sortBy" class="form-select" @bind="sortBy" @bind:after="OnSortChanged">
                    <option value="price_asc">Price: Low to High</option>
                    <option value="price_desc">Price: High to Low</option>
                    <option value="name_asc">Name: A-Z</option>
                    <option value="rating_desc">Rating: Highest</option>
                </select>
            </div>
            <div class="results-info">
                @if (result is not null && result.TotalCount > 0)
                {
                    var start = (result.Page - 1) * result.PageSize + 1;
                    var end = Math.Min(result.Page * result.PageSize, result.TotalCount);
                    <span>Showing @start–@end of @result.TotalCount products</span>
                }
            </div>
        </div>

        <!-- Product Grid -->
        @if (isLoading)
        {
            <div class="loading-state">
                <p><em>Loading products...</em></p>
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="empty-state">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <ProductCard Product="product"
                                 OnProductSelected="OnProductSelected"
                                 OnAddToCart="OnAddToCart" />
                }
            </div>

            <!-- Pagination -->
            <nav class="pagination-controls" aria-label="Product pagination">
                <button class="btn btn-outline-primary"
                        disabled="@(currentPage <= 1)"
                        @onclick="PreviousPage">
                    Previous
                </button>

                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn @(pageNum == currentPage ? "btn-primary" : "btn-outline-primary")"
                            @onclick="() => GoToPage(pageNum)">
                        @pageNum
                    </button>
                }

                <button class="btn btn-outline-primary"
                        disabled="@(currentPage >= totalPages)"
                        @onclick="NextPage">
                    Next
                </button>
            </nav>
        }
    </main>
</div>

@code {
    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private PagedResult<Product>? result;
    private bool isLoading;
    private string? errorMessage;

    private int totalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await LoadProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load categories: {ex.Message}";
        }
    }

    private async Task LoadProducts()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
            result = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task PreviousPage()
    {
        if (currentPage > 1)
        {
            currentPage--;
            await LoadProducts();
        }
    }

    private async Task NextPage()
    {
        if (currentPage < totalPages)
        {
            currentPage++;
            await LoadProducts();
        }
    }

    private async Task OnAddToCart(Product product)
    {
        // Placeholder for add to cart functionality
        await Task.CompletedTask;
    }
}
"}

